// BOOT button toggles the LED and prints the chip temperature
const uint8_t BOOT_PIN = 0;                // BOOT button (SW1) on GPIO0
const uint8_t LED_PIN = 4;
const unsigned long DEBOUNCE_MS = {{p:debounceMs}};

bool ledOn = false;
int lastReading = HIGH;
int stable = HIGH;
unsigned long changedAt = 0;
int presses = 0;

void setup() {
  Serial.begin(115200);
  pinMode(BOOT_PIN, INPUT_PULLUP);         // pressed = LOW, released = HIGH
  pinMode(LED_PIN, OUTPUT);
  Serial.println("press BOOT");
}

void loop() {
  int reading = digitalRead(BOOT_PIN);
  if (reading != lastReading) {            // the reading changed: restart the timer
    changedAt = millis();
    lastReading = reading;
  }
  if (millis() - changedAt >= DEBOUNCE_MS && reading != stable) {
    stable = reading;
    if (stable == LOW) {                   // a clean press
      presses++;
      ledOn = !ledOn;
      digitalWrite(LED_PIN, ledOn ? HIGH : LOW);
      float chipC = temperatureRead();     // die temperature in °C
      Serial.printf("BOOT pressed #%d, chip %.1f C\n", presses, chipC);
    }
  }
}

